//! Exhaustive C-semantics matrix: every numeric type x every valid legal
//! operation against every other numeric type, asserting the exact value C
//! 6.3.1.8 (integer promotions + usual arithmetic conversions) requires.
//! int=32/long=64; narrower-than-int operands promote to signed int;
//! unsignedness survives only when an unsigned operand is as wide as the
//! promoted result; shifts take the type of the promoted left operand
//! (C 6.5.7). C-undefined cases (signed overflow, div/mod by zero, shift >=
//! width, INT_MIN/-1) are excluded by construction.
//!
//! Each test is one program containing every case for a type pair; a case
//! failure returns its 1-based index so the mismatch localizes without
//! running tens of thousands of JIT instances.

use pepper_codegen::CodeGenerator;

fn compile_jit_with_runtime(source: &str) -> i32 {
    let mut module = pepper_driver::compiler::compile_with_runtime("test.pep", source).expect("compile");
    let ctx = inkwell::context::Context::create();
    let mut generator = CodeGenerator::new(&ctx, "test");
    generator.jit_execute(&mut module, "test").expect("jit")
}


