#[test]
fn u_i16() {
    let r = compile_jit_with_runtime(r#"test(): int {
    { i16 a = -32768; if (-a != 32768) { return 1; } }
    { i16 a = -32768; if (~a != 32767) { return 2; } }
    { i16 a = -7; if (-a != 7) { return 3; } }
    { i16 a = -7; if (~a != 6) { return 4; } }
    { i16 a = -1; if (-a != 1) { return 5; } }
    { i16 a = -1; if (~a != 0) { return 6; } }
    { i16 a = 0; if (-a != 0) { return 7; } }
    { i16 a = 0; if (~a != -1) { return 8; } }
    { i16 a = 7; if (-a != -7) { return 9; } }
    { i16 a = 7; if (~a != -8) { return 10; } }
    { i16 a = 32767; if (-a != -32767) { return 11; } }
    { i16 a = 32767; if (~a != -32768) { return 12; } }
    return 0;
}
"#);
    assert_eq!(r, 0, "first failing case index");
}

